def paragraphs(path):
    with ZipFile(path) as archive:doc=ET.fromstring(archive.read('word/document.xml'))
    ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
    return [''.join(t.text or '' for t in p.findall('.//w:t',ns)) for p in doc.findall('.//w:p',ns)]

def main():
    inherited=json.loads((AUDIT/'LOW_NECROMANCY_SPELL_SOURCE_PREPARATION.json').read_text(encoding='utf-8'))
    protected=deepcopy(inherited['protectedFiles']);assert all(sha(GAME/p)==h for p,h in protected.items())
