    book_binding={'sourceFile':primary.relative_to(GAME).as_posix(),'sourceSha256':sha(primary),'paragraphConvention':'zero-based all w:p including tables','paragraphs':[{'paragraph':i,'text':ps[i]} for i in range(start,end)],'currentExtractFile':book_path.relative_to(GAME).as_posix(),'currentExtractStartLine':book_start+1,'currentExtractEndLine':book_end,'exactParagraphEquality':True}
