    guides={'EXPEDITION_STRUCTURE_CANON.md':None,'REPUTATION.md':None,'STRAIN_PLAYTEST.md':None,'CORE_RESOLUTION_PLAYTEST.md':None,'COMBAT_ACTION_PLAYTEST.md':None,'CHARACTER_CREATION_PLAYTEST.md':None,'BODY_EQUIPMENT_PLAYTEST.md':None,'EQUIPMENT_ACQUISITION_PLAYTEST.md':None,'CRAFTING_HARVEST_PLAYTEST.md':None,'COOKING_RECIPE_PLAYTEST.md':['Food mass and the food ledger','Cooking, stabilization and storage'],'ANCESTRY_BACKGROUND_PLAYTEST.md':['Trait procedures and source-specific exceptions','Background procedures','Remaining dependencies'],'ANCESTRY_SPELL_SUPPLEMENT_PLAYTEST.md':None,'CREATURE_LIFECYCLE_PLAYTEST.md':['At the table','Different kinds of creature life'],'HEALING_DEATH_PLAYTEST.md':['Actual resurrection and retained consequences','Lethal tracks after return or replacement'],'CONDITIONS_PLAYTEST.md':['Staggered','Stunned','Paralyzed']}
    current=[]
