    data={'status':'prepared-not-sent; bounded source/interface conference','scope':'The playable descent-to-Haven loop,source authority andfinite operating gaps. Not a full setting/faction or cosmology review,notfinaljointflowapproval.','decisionCases':[{'id':f'FL-{i+1:02}','title':title,'question':q} for i,(title,q) in enumerate(CASES)],'sourceFindings':source_findings,'domainAuthority':authority,'loopSections':loop_sections,'playerExpeditionSource':book_binding,'coreEconomySource':core_economy,'currentGoverningExcerpts':current,'runtimeReputationEvidence':{'file':rep_path.relative_to(GAME).as_posix(),'sha256':sha(rep_path),'excerpts':runtime,'status':'Read-only implementation evidence; no code executed or source changed.'},'runtimeExpeditionMirror':dungeon,'actualSupplyEquipmentRecords':supplies,'reviewedSpellCounterparts':spell_records,'counts':counts,'checks':[{'name':n,'pass':ok} for n,ok in checks],'protectedFiles':protected,'newMechanicalApprovals':0,'sourceInformationDeleted':0,'cosmology':'post-push only; seasonalchapter20excluded andsourcecosmictermsnotadjudicated','next':'Rebase after Fishingreviewandremainingdependencies. Send sourceconferenceonceavailable,thenauthoranexecutableflowandexamplesforseparateexactreview.'}
    dump(AUDIT/'EXPEDITION_HAVEN_FLOW_SOURCE_PREPARATION.json',data)
